//#region src/lib/analytics/consent.ts
var KEY = "dakia_consent_v2";
var DENIED = {
	analytics_storage: "denied",
	ad_storage: "denied",
	ad_user_data: "denied",
	ad_personalization: "denied",
	decided: false,
	updatedAt: null
};
function loadConsent() {
	try {
		const raw = localStorage.getItem(KEY);
		if (!raw) return { ...DENIED };
		const parsed = JSON.parse(raw);
		if (parsed.analytics_storage !== "granted" && parsed.analytics_storage !== "denied") return { ...DENIED };
		return parsed;
	} catch {
		return { ...DENIED };
	}
}
function saveConsent(next) {
	localStorage.setItem(KEY, JSON.stringify(next));
}
function applyGtagConsent(state) {
	const gtag = window.gtag;
	if (typeof gtag !== "function") return;
	gtag("consent", "update", {
		analytics_storage: state.analytics_storage,
		ad_storage: state.ad_storage,
		ad_user_data: state.ad_user_data,
		ad_personalization: state.ad_personalization
	});
}
function hasAnalyticsConsent() {
	return loadConsent().analytics_storage === "granted";
}
//#endregion
export { saveConsent as i, hasAnalyticsConsent as n, loadConsent as r, applyGtagConsent as t };
